// Positional parameter order IS the 0x19 wire order: index i is the
// int16 at param offset i. Missing offsets use defaultValue, extra ones
// are ignored.
enum class ParamKind : std::uint8_t { Int = 0, Bool = 1, Enum = 2 };

struct ParamSpec {
  const char* key;
  const char* label;
  ParamKind kind;
  std::int32_t min;
  std::int32_t max;
  std::int32_t defaultValue;
  const char* unit;             // "" when unitless
  const char* const* choices;   // nullptr for int/bool
  std::uint8_t choiceCount;
  std::uint8_t index;           // == 0x19 positional offset
};

// Route legality, not wire data: a generator emits without an input and
// may head a generator route; a modifier needs an incoming message.
enum class PipeRole : std::uint8_t { Modifier = 0, Generator = 1 };

struct PipeSpec {
  std::uint8_t id;
  const char* key;
  const char* name;
  const char* shortName;
  const char* category;
  PipeRole role;
  bool clocked;
  const char* docs;
  const ParamSpec* params;
  std::uint8_t paramCount;
};

// Per-pipe channel scope, carried alongside the positional params on the
// 0x19 offset-0 chunk: bit n admits channel n, every other message passes
// the pipe unchanged. 0xFFFF is all channels, 0 makes the pipe inert.
struct ChannelScopeSpec {
  const char* key;
  std::uint16_t min;
  std::uint16_t max;
  std::uint16_t defaultValue;
  const char* docs;
};

