// Route legality helper: true when the pipe emits from the tick grid and
// may be the head of a generator route (src = kSrcGenerator).
constexpr bool pipeIsGenerator(std::uint8_t id) {
  for (const PipeSpec& pipe : kPipes)
    if (pipe.id == id) return pipe.role == PipeRole::Generator;
  return false;
}

// Route legality helper for the documented role names (schema/docs only).
constexpr const char* pipeRoleName(PipeRole role) {
  return role == PipeRole::Generator ? "generator" : "modifier";
}

constexpr const PipeSpec* pipeSpecById(std::uint8_t id) {
  for (const PipeSpec& pipe : kPipes)
    if (pipe.id == id) return &pipe;
  return nullptr;
}

constexpr const ParamSpec* pipeParamSpec(std::uint8_t id, std::size_t index) {
  const PipeSpec* pipe = pipeSpecById(id);
  if (pipe == nullptr || index >= pipe->paramCount) return nullptr;
  return &pipe->params[index];
}

// Schema default for a missing 0x19 positional param; 0 when the id or
// offset is outside the schema (an unconfigured pipe must stay harmless).
constexpr std::int32_t pipeDefaultParam(std::uint8_t id, std::size_t index) {
  const ParamSpec* param = pipeParamSpec(id, index);
  return param == nullptr ? 0 : param->defaultValue;
}

